import React, { useState, useEffect } from "react";
import axios from "axios";

const Dashboard = ({ userId }) => {
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        const response = await axios.get("http://localhost:5000/dashboard", {
          headers: { "user-id": userId },
        });
        console.log("Dashboard Response:", response.data); // Debug log
        setDashboardData(response.data);
      } catch (err) {
        setError("Failed to fetch dashboard data");
        console.error("Fetch error:", err.response ? err.response.data : err); // Detailed error
      } finally {
        setLoading(false);
      }
    };
    if (userId) fetchDashboardData();
  }, [userId]);

  if (loading) return <p style={{ color: "white" }}>Loading...</p>;
  if (error) return <p style={{ color: "white" }}>{error}</p>;
  if (!dashboardData || !dashboardData.user)
    return <p style={{ color: "white" }}>No dashboard data available</p>;

  const { user, wishlist, recentActivity } = dashboardData;

  return (
    <div
      style={{ padding: "20px", color: "white", backgroundColor: "#1a1a1a" }}
    >
      <h2>My Dashboard</h2>
      <div>
        <h3>Welcome, {user.full_name || "Guest"}</h3>
        <p>Email: {user.email || "N/A"}</p>
      </div>
      <h3>My Wishlist</h3>
      {wishlist && wishlist.length > 0 ? (
        <ul>
          {wishlist.map((house) => (
            <li key={house.id} style={{ marginBottom: "10px" }}>
              {house.address} - ${house.price || "N/A"}
              {house.images && house.images.length > 0 && (
                <img
                  src={`http://localhost:5000${house.images[0]}`}
                  alt="House"
                  style={{ width: "100px", marginLeft: "10px" }}
                />
              )}
            </li>
          ))}
        </ul>
      ) : (
        <p>No items in your wishlist</p>
      )}
      <h3>Recent Activity</h3>
      {recentActivity && recentActivity.length > 0 ? (
        <ul>
          {recentActivity.map((activity, index) => (
            <li key={index} style={{ marginBottom: "10px" }}>
              {activity.address || "N/A"} - ${activity.price || "N/A"}
            </li>
          ))}
        </ul>
      ) : (
        <p>No recent activity</p>
      )}
    </div>
  );
};

export default Dashboard;
